int load_tss_state(struct x86_emulate_ctxt *ctxt, struct tss_segment_16 *tss) {
    /* Load instruction pointer and flags from TSS */
    ctxt->regs->ip = tss->eip;
    ctxt->regs->flags = tss->eflags;

    /* Write general-purpose registers from TSS */
    ctxt->regs->ax = tss->eax;
    ctxt->regs->cx = tss->ecx;
    ctxt->regs->dx = tss->edx;
    ctxt->regs->bx = tss->ebx;
    ctxt->regs->sp = tss->esp;
    ctxt->regs->bp = tss->ebp;
    ctxt->regs->si = tss->esi;
    ctxt->regs->di = tss->edi;

    /* Set segment selectors */
    ctxt->regs->cs = tss->cs;
    ctxt->regs->ds = tss->ds;
    ctxt->regs->es = tss->es;
    ctxt->regs->fs = tss->fs;
    ctxt->regs->gs = tss->gs;
    ctxt->regs->ss = tss->ss;

    /* Load segment descriptors and handle faults */
    int result = load_segment_descriptors(ctxt);
    if (result != X86EMUL_CONTINUE)
        return result;

    return X86EMUL_CONTINUE;
}

