int load_task_state_16(struct x86_emulate_ctxt *ctxt, struct tss_segment_16 *tss)
{
    int rc;

    /* Initialize emulator context from TSS */
    ctxt->regs[VCPU_REGS_RIP] = tss->eip;
    ctxt->regs[VCPU_REGS_RFLAGS] = tss->eflags;

    /* Load general-purpose registers */
    ctxt->regs[VCPU_REGS_RAX] = tss->eax;
    ctxt->regs[VCPU_REGS_RCX] = tss->ecx;
    ctxt->regs[VCPU_REGS_RDX] = tss->edx;
    ctxt->regs[VCPU_REGS_RBX] = tss->ebx;
    ctxt->regs[VCPU_REGS_RSP] = tss->esp;
    ctxt->regs[VCPU_REGS_RBP] = tss->ebp;
    ctxt->regs[VCPU_REGS_RSI] = tss->esi;
    ctxt->regs[VCPU_REGS_RDI] = tss->edi;

    /* Load segment registers */
    ctxt->segment_selector[VCPU_SREG_CS] = tss->cs;
    ctxt->segment_selector[VCPU_SREG_DS] = tss->ds;
    ctxt->segment_selector[VCPU_SREG_ES] = tss->es;
    ctxt->segment_selector[VCPU_SREG_FS] = tss->fs;
    ctxt->segment_selector[VCPU_SREG_GS] = tss->gs;
    ctxt->segment_selector[VCPU_SREG_SS] = tss->ss;

    /* Load segment descriptors */
    rc = load_segment_descriptor(ctxt, VCPU_SREG_CS, tss->cs);
    if (rc != X86EMUL_CONTINUE)
        return rc;
    rc = load_segment_descriptor(ctxt, VCPU_SREG_DS, tss->ds);
    if (rc != X86EMUL_CONTINUE)
        return rc;
    rc = load_segment_descriptor(ctxt, VCPU_SREG_ES, tss->es);
    if (rc != X86EMUL_CONTINUE)
        return rc;
    rc = load_segment_descriptor(ctxt, VCPU_SREG_FS, tss->fs);
    if (rc != X86EMUL_CONTINUE)
        return rc;
    rc = load_segment_descriptor(ctxt, VCPU_SREG_GS, tss->gs);
    if (rc != X86EMUL_CONTINUE)
        return rc;
    rc = load_segment_descriptor(ctxt, VCPU_SREG_SS, tss->ss);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    return X86EMUL_CONTINUE;
}
